app.get('/healthz', (req, res) => {
  const databaseUrl = process.env.DATABASE_URL || '';

  // Parse DATABASE_URL to get host and port
  // Expected format: postgres://user:pass@host:port/database
  const match = databaseUrl.match(/postgres:\/\/[^:]+:[^@]+@([^:]+):(\d+)\//);

  if (!match) {
    console.error('Failed to parse DATABASE_URL:', databaseUrl);
    return res.status(503).json({ db: 'error', error: 'missing or invalid DATABASE_URL' });
  }

  const [_, host, port] = match;

  // Try to connect to the database host
  const socket = new net.Socket();
  const timeout = 5000; // 5 second timeout

  socket.setTimeout(timeout);

  socket.connect(port, host, () => {
    socket.destroy();
    res.status(200).json({ db: 'ok' });
  });

  socket.on('error', (err) => {
    socket.destroy();
    console.error('Database connectivity check failed:', err.message);
    res.status(503).json({ db: 'error', error: 'database unreachable' });
  });

  socket.on('timeout', () => {
    socket.destroy();
    console.error('Database connectivity check timed out');
    res.status(503).json({ db: 'error', error: 'database timeout' });
  });
});

